"""U5 の確認用: 突き合わせの比べ方を、一時的なリポジトリで試す (コミットしない)。"""
import subprocess, sys

def git(*a, cwd="."):
    return subprocess.run(["git", *a], cwd=cwd, check=True, text=True, capture_output=True).stdout

def snapshot(main):
    refs = {}
    for l in git("for-each-ref", "--format=%(refname:short) %(objectname:short)", "refs/heads", cwd=main).splitlines():
        n, s = l.split(" ")
        refs[n] = s
    entries, cur = [], {}
    for l in git("worktree", "list", "--porcelain", cwd=main).splitlines():
        if not l:
            entries.append(cur); cur = {}
            continue
        k, _, v = l.partition(" ")
        cur[k] = v
    if cur:
        entries.append(cur)
    first = entries[0]
    if "branch" in first:
        main_head = first["branch"].removeprefix("refs/heads/")
    else:
        main_head = first.get("HEAD", "")
    wb = [e["branch"].removeprefix("refs/heads/") for e in entries[1:] if "branch" in e]
    return {"refs": refs, "main_head": main_head, "worktree_branches": wb}

def compare(before, after):
    excl = set(before["worktree_branches"]) | set(after["worktree_branches"])
    b = {k: v for k, v in before["refs"].items() if k not in excl}
    a = {k: v for k, v in after["refs"].items() if k not in excl}
    diffs = []
    for k in sorted(set(a) | set(b)):
        if a.get(k) != b.get(k):
            diffs.append(f"{k}: {b.get(k)} -> {a.get(k)}")
    if before["main_head"] != after["main_head"]:
        diffs.append(f"HEAD of main: {before['main_head']} -> {after['main_head']}")
    return diffs

if __name__ == "__main__":
    pass
EOF
